package com.johnny.hotel.cms;import com.johnny.hotel.cms.CmsModels.*;import com.johnny.hotel.common.Result;import lombok.RequiredArgsConstructor;import org.springframework.web.bind.annotation.*;import java.util.List;
@RestController@RequiredArgsConstructor@RequestMapping("/api/public/site")public class PublicSiteController{private final CmsService service;@GetMapping("/pages/{slug}")public Result<PublicPage>page(@PathVariable String slug,@RequestParam(defaultValue="zh-CN")String locale){return Result.success(service.publicPage(slug,locale));}@GetMapping("/navigation")public Result<List<PublicNavigation>>nav(@RequestParam(defaultValue="zh-CN")String locale){return Result.success(service.publicNav(locale));}@GetMapping("/promotions")public Result<List<PublicPromotion>>promos(@RequestParam(defaultValue="zh-CN")String locale){return Result.success(service.publicPromotions(locale));}@GetMapping("/location")public Result<PublicLocation>location(@RequestParam(defaultValue="zh-CN")String locale){return Result.success(service.publicLocation(locale));}@GetMapping("/scenes")public Result<List<PublicScene>>scenes(@RequestParam(defaultValue="zh-CN")String locale){return Result.success(service.publicScenes(locale));}}
